"""Independent former failure oracles plus complete read-only descriptor invariance."""
import hashlib,json
from playwright.sync_api import sync_playwright
from test_mobile_rendering import ROOT,html
source=(ROOT/'assets/game.js').read_text()
probe="window.__districtAcceptance={cache:()=>{__townTest.reset('regional',42);__townTest.step(1);const before=JSON.stringify(G),cached=JSON.parse(JSON.stringify(urbanSpatial().profiles));invalidateUrban();const fresh=urbanSpatial().profiles,changes=[];for(const [key,row]of Object.entries(cached))for(const field of Object.keys(row))if(JSON.stringify(row[field])!==JSON.stringify(fresh[key][field]))changes.push({key,field,cached:row[field],fresh:fresh[key][field]});return {changes,modelUnchanged:before===JSON.stringify(G)};},review:()=>{__townTest.reset('regional',42);__townTest.step(720);invalidateUrban();const c=urbanSpatial(),entry=Object.entries(c.profiles).find(([k,p])=>p.character!==c.blocks[k].character&&c.blocks[k].buildings.length>=3);if(!entry)throw Error('No actual observed/base character difference');const [key,p]=entry,u=ensureUrban(),base=G.day,rngBefore=rngState;u.districts[key]={name:'Review control',character:c.blocks[key].character,since:1,changed:1};const stages=[];for(const offset of [0,30,60,90]){G.day=base+offset;u.lastReview=-1;invalidateUrban();urbanDistrictReview();stages.push({day:G.day,observed:urbanSpatial().profiles[key].character,archived:JSON.parse(JSON.stringify(u.districts[key]))})}return {key,stages,rngBefore,rngAfter:rngState};}};\nwindow.__districtReadOnly=()=>{const c=urbanSpatial(),before=archivePayload(),money=totalMoney(),rng=rngState,items=G.buildings.map(b=>urbanBuildingDescriptor(b));for(let i=0;i<8;i++){if(urbanSpatial()!==c)throw Error('Reader rebuilt cache');for(const b of G.buildings)urbanBuildingDescriptor(b)}return {cacheStable:true,descriptors:items.length,completeArchiveUnchanged:archivePayload()===before,moneyUnchanged:money===totalMoney(),rngUnchanged:rng===rngState,hasNoFakeFinance:!Object.values(c.profiles).some(p=>p.character==='Financial district'&&(!p.expandedBankBranches||p.openBankBranches<2||p.financialActivity<=0))}};"
with sync_playwright()as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=b.new_page();errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.set_content(html);p.add_script_tag(content=source.replace('// SOURCE: 99-instrumentation.js',probe+'\n// SOURCE: 99-instrumentation.js'));p.locator('#newTown').click();p.locator('#pause').click();cache=p.evaluate('__districtAcceptance.cache()');review=p.evaluate('__districtAcceptance.review()');reads=p.evaluate('__districtReadOnly()');b.close()
assert cache['modelUnchanged']and cache['changes']==[],cache
stages=review['stages'];assert all(s['archived']['character']==stages[0]['archived']['character']and s['archived']['character']!=s['observed']for s in stages[:3]),stages
assert stages[-1]['archived']['character']==stages[-1]['observed']and 'proposed'not in stages[-1]['archived'],stages
assert review['rngBefore']==review['rngAfter']and all(reads.values())and not errors,(review,reads,errors)
print(json.dumps({'source_sha256':hashlib.sha256(source.encode()).hexdigest(),'formerStaleCacheFailure':cache,'formerTransitionFailure':review,'readOnly':reads,'errors':errors},indent=2))
